    disclaimerSection1Body:
      "ShiftPulse \u044F\u0432\u043B\u044F\u0435\u0442\u0441\u044F \u0438\u043D\u0441\u0442\u0440\u0443\u043C\u0435\u043D\u0442\u043E\u043C \u0434\u043B\u044F \u043B\u0438\u0447\u043D\u043E\u0433\u043E \u043F\u043B\u0430\u043D\u0438\u0440\u043E\u0432\u0430\u043D\u0438\u044F, \u0443\u0447\u0435\u0442\u0430 \u0438 \u043E\u0440\u0433\u0430\u043D\u0438\u0437\u0430\u0446\u0438\u0438 \u0441\u043C\u0435\u043D\u043D\u043E\u0439 \u0440\u0430\u0431\u043E\u0442\u044B. \u0412\u0441\u0435 \u0432\u044B\u0447\u0438\u0441\u043B\u0435\u043D\u0438\u044F \u0431\u0430\u0437\u043E\u0432\u043E\u0433\u043E \u0434\u043E\u0445\u043E\u0434\u0430, \u0441\u0432\u0435\u0440\u0445\u0443\u0440\u043E\u0447\u043D\u044B\u0445, \u043D\u0430\u0434\u0431\u0430\u0432\u043E\u043A \u0437\u0430 \u043D\u043E\u0447\u043D\u044B\u0435 \u0447\u0430\u0441\u044B \u0438 \u0432\u044B\u0447\u0435\u0442\u043E\u0432 \u0437\u0430 \u043F\u0435\u0440\u0435\u0440\u044B\u0432\u044B \u043D\u043E\u0441\u044F\u0442 \u043E\u0440\u0438\u0435\u043D\u0442\u0438\u0440\u043E\u0432\u043E\u0447\u043D\u044B\u0439 \u043E\u0446\u0435\u043D\u043E\u0447\u043D\u044B\u0439 \u0445\u0430\u0440\u0430\u043A\u0442\u0435\u0440 \u0438 \u0441\u043B\u0443\u0436\u0430\u0442 \u0434\u043B\u044F \u043B\u0438\u0447\u043D\u043E\u0433\u043E \u043F\u043B\u0430\u043D\u0438\u0440\u043E\u0432\u0430\u043D\u0438\u044F \u0431\u044E\u0434\u0436\u0435\u0442\u0430. \u041E\u043D\u0438 \u041D\u0415 \u044F\u0432\u043B\u044F\u044E\u0442\u0441\u044F \u043E\u0444\u0438\u0446\u0438\u0430\u043B\u044C\u043D\u043E\u0439 \u043D\u0430\u043B\u043E\u0433\u043E\u0432\u043E\u0439, \u0431\u0443\u0445\u0433\u0430\u043B\u0442\u0435\u0440\u0441\u043A\u043E\u0439 \u0438\u043B\u0438 \u044E\u0440\u0438\u0434\u0438\u0447\u0435\u0441\u043A\u043E\u0439 \u043A\u043E\u043D\u0441\u0443\u043B\u044C\u0442\u0430\u0446\u0438\u0435\u0439.",
